"""Dump ParagraphMaker.make_paragraphs results as JSON for a given implementation."""
from __future__ import unicode_literals, print_function

import sys
import json
import traceback

sys.path.insert(0, "/tmp/eqtest_struct")
from cases import CASES  # noqa

import justext  # noqa
import justext.core as core  # noqa


def para_dict(p):
    d = {}
    for attr in ("dom_path", "xpath", "text_nodes", "chars_count_in_links",
                 "tags_count", "class_type"):
        d[attr] = getattr(p, attr)
    # properties
    for attr in ("is_heading", "is_boilerplate", "text", "words_count"):
        try:
            d[attr] = getattr(p, attr)
        except Exception as e:
            d[attr] = "EXC:%r" % (e,)
    d["len"] = len(p)
    d["contains_text"] = p.contains_text()
    d["links_density"] = round(p.links_density(), 12)
    d["class_name"] = type(p).__name__
    return d


def run_case(html, use_preprocessor):
    dom = core.html_to_dom(html)
    if use_preprocessor:
        dom = core.preprocessor(dom)
    paras = core.ParagraphMaker.make_paragraphs(dom)
    return [para_dict(p) for p in paras]


def main():
    out = {
        "__file__": justext.__file__,
        "core_file": core.__file__,
        "PARAGRAPH_TAGS": sorted(core.PARAGRAPH_TAGS),
        "PARAGRAPH_TAGS_type": type(core.PARAGRAPH_TAGS).__name__,
        "cases": {},
    }
    for name in sorted(CASES):
        html = CASES[name]
        for mode, pre in (("raw", False), ("pre", True)):
            key = "%s::%s" % (name, mode)
            try:
                out["cases"][key] = {"ok": True, "paras": run_case(html, pre)}
            except Exception as e:
                out["cases"][key] = {
                    "ok": False,
                    "exc": type(e).__name__,
                    "msg": str(e),
                    "tb": traceback.format_exc().splitlines()[-3:],
                }
    json.dump(out, sys.stdout, indent=1, sort_keys=True, ensure_ascii=False)


